    description: '北极熊是一种海冰依赖的海洋熊类：长颈、小耳、宽掌和厚脂肪层让它能在漂移冰面与冰间水道移动，并在环斑海豹的呼吸孔或雪下育幼穴旁静候。五个范围国把它划为二十个管理亚种群，局地短期趋势从增加到下降不一，且一半仍资料不足；这也是 IUCN 全球趋势继续标为未知的原因。长期风险却清晰指向温室气体驱动的海冰缩短和猎场错位。陆地食物只能提供有限补充，保护必须把减排、关键冰上与产仔生境、原住民共同管理、冲突预防、污染和工业风险控制放在同一框架中。',
